{
  "title": "The Gilded Cage",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined city gates.",
      "visual_description": "Massive iron gates, twisted and rusted, stand half-open beneath crumbling stone archways. Ivy and old royal banners flutter in a dusty wind.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings.",
      "visual_description": "A huddle of ragged citizens in a narrow alley, their faces pale, eyes darting toward the high towers.",
      "characters": ["Townspeople", "Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march past a cursed fountain.",
      "visual_description": "Soldiers in blackened plate armor clank in unison, their visors down, passing a dry fountain whose stone cherubs weep red rust.",
      "characters": ["Armored Patrol", "Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 4,
      "caption": "The party hides behind an overturned cart.",
      "visual_description": "Wooden spokes splintered, a canvas tarp painted with a faded sun, the team crouches low as boots echo on cobblestones.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 5,
      "caption": "A magic door glows with runes on a forgotten wall.",
      "visual_description": "The door pulses with blue light, runes spiraling outward, surrounded by a stone arch covered in old moss.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 6,
      "caption": "Kael picks the lock of a side gate.",
      "visual_description": "Kael's slender fingers work a set of picks into a rusted lock, sweat on his brow, while Elara keeps watch with a drawn bow.",
      "characters": ["Kael", "Elara"]
    },
    {
      "scene_number": 7,
      "caption": "Inside a courtyard, an old statue of a king weeps.",
      "visual_description": "A marble king on a pedestal, cracked, tears of water trickling from its stone eyes into a stagnant pool.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 8,
      "caption": "Whispers of dragons echo from a nearby tower.",
      "visual_description": "A twisted spire, black against the grey sky, with scorch marks around its narrow windows. A low rumble shakes the ground.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 9,
      "caption": "The party enters a cursed tower's base.",
      "visual_description": "A circular chamber with a spiral staircase, walls covered in faded tapestries of battles and dragons. Dust motes hang thick in the air.",
      "characters": ["Elara", "Kael", "Mira"]
    },
    {
      "scene_number": 10,
      "caption": "They find the prisoner chained to a pillar.",
      "visual_description": "A figure in tattered robes, chains around wrists and ankles, a iron collar bolted to a stone pillar carved with runes.",
      "characters": ["Elara", "Kael", "Mira", "Finn"]
    },
    {
      "scene_number": 11,
      "caption": "Kael works on the collar's lock.",
      "visual_description": "Kael's tools click inside the collar mechanism, sparks fly, Mira holds a torch and Elara watches the stairs.",
      "characters": ["Kael", "Mira", "Elara", "Finn"]
    },
    {
      "scene_number": 12,
      "caption": "The runes on the pillar flare red.",
      "visual_description": "Glowing crimson symbols pulse, sending a shudder through the floor. A distant roar echoes up the tower.",
      "characters": ["Elara", "Kael", "Mira", "Finn"]
    },
    {
      "scene_number": 13,
      "caption": "Armored patrols rush into the tower base.",
      "visual_description": "Boots thunder on stone, the black-armored soldiers pour through the doorway, swords drawn, their visors reflecting torchlight.",
      "characters": ["Armored Patrol", "Elara", "Kael", "Mira", "Finn"]
    },
    {
      "scene_number": 14,
      "caption": "Elara fires an arrow that shatters a chandelier.",
      "visual_description": "The arrow splits the chain holding a massive iron chandelier, which crashes down in a shower of sparks and wax, blocking the entrance.",
      "characters": ["Elara", "Armored Patrol"]
    },
    {
      "scene_number": 15,
      "caption": "The party flees through a crumbling corridor.",
      "visual_description": "They run, kicking up dust, past frescoes of ancient kings, as stones fall from the ceiling and the roar grows louder.",
      "characters": ["Elara", "Kael", "Mira", "Finn"]
    },
    {
      "scene_number": 16,
      "caption": "They burst onto the bridge under a twilight sky.",
      "visual_description": "A long stone bridge spans a dry riverbed, broken railings, with the city gates visible at the far end. The sky is orange and red.",
      "characters": ["Elara", "Kael", "Mira", "Finn"]
    },
    {
      "scene_number": 17,
      "caption": "A great shadow passes overhead—a dragon.",
      "visual_description": "A massive winged silhouette blocks the setting sun, scales glinting, a roar that shakes the bridge as the party runs.",
      "characters": ["Elara", "Kael", "Mira", "Finn"]
    },
    {
      "scene_number": 18,
      "caption": "They escape beyond the gates as the city collapses.",
      "visual_description": "The team crosses the threshold, the bridge crumbling behind them, towers falling in clouds of dust, and they vanish into the forest.",
      "characters": ["Elara", "Kael", "Mira", "Finn"]
    }
  ]
}

